interface RepoContext {
  text: string;
  tokenCount: number;
}

interface DocGenerationOptions {
  model?: string;
  maxTokens?: number;
  customInstructions?: string;
}

interface DocResponse {
  content: string;
  model: string;
  status: 'success' | 'error';
  error?: string;
}

const MAX_REPO_SIZE_MB = 100;
const INITIAL_RETRY_DELAY = 1000;
const MAX_RETRIES = 3;

// File patterns to include in documentation
const includePatterns = [
  '*.md',
  '*.txt',
  'package.json',
  'requirements.txt',
  'setup.py',
  'readme',
  'license'
];

// Patterns to ignore
const ignorePatterns = [
  'node_modules/**',
  'dist/**',
  'build/**',
  '.git/**',
  '*.test.*',
  '*.spec.*',
  'coverage/**'
];

