async function validateAndGetRepoInfo(username: string, reponame: string): Promise<{ owner: string; repo: string; defaultBranch: string }> {
  // First try to get context from git remote
  const repoContext = await getRepoContext();
  if (repoContext) {
    console.log("Found repository context from git remote:", repoContext);
    
    // Fetch repository details to get the default branch
    const headers = await getGitHubHeaders();
    //@ts-ignore
    const response = await fetch(
      `https://api.github.com/repos/${repoContext.owner}/${repoContext.repo}`,
      { headers }
    );

    if (response.ok) {
      const data: any = await response.json();
      return {
        owner: repoContext.owner,
        repo: repoContext.repo,
        defaultBranch: data.default_branch || 'main'
      };
    }
  }

  // If git remote context is not available, try with provided username/reponame
  const headers = await getGitHubHeaders();
  //@ts-ignore
  const response = await fetch(
    `https://api.github.com/repos/${username}/${reponame}`,
    { headers }
  );

  if (!response.ok) {
    throw new Error(`Repository not found at ${username}/${reponame}. Please verify the repository path.`);
  }

  const data: any = await response.json();
  return {
    owner: data.owner.login,
    repo: data.name,
    defaultBranch: data.default_branch || 'main'
  };
}

export async function getGithubRepoContext(username: string, reponame: string, branch?: string): Promise<RepoContext> {
  try {
    // Validate and get correct repository information
    const repoInfo = await validateAndGetRepoInfo(username, reponame);
    const repoIdentifier = `${repoInfo.owner}/${repoInfo.repo}`;
    console.log("Validated repository details:", repoInfo);

    // Use validated branch or default branch
    const actualBranch = branch || repoInfo.defaultBranch;
    console.log(`Using branch: ${actualBranch}`);

    // Check repository size
    const headers = await getGitHubHeaders();
    //@ts-ignore
    const sizeResponse = await fetch(
      `https://api.github.com/repos/${repoInfo.owner}/${repoInfo.repo}`,
      { headers }
    );

    if (sizeResponse.ok) {
      const repoData: any = await sizeResponse.json();
      const sizeInMB = repoData.size / 1024;
      console.log(`Repository size: ${Math.round(sizeInMB)}MB (limit: ${MAX_REPO_SIZE_MB}MB)`);

      if (sizeInMB > MAX_REPO_SIZE_MB) {
        throw new Error(
          `Repository ${repoIdentifier} is too large (${Math.round(sizeInMB)}MB) to process.\n` +
          `Please increase limit, clone locally, or exclude unnecessary files.`
        );
      }
    }

    // Get GitHub token for authentication
    const authHeader = headers.Authorization;
    if (!authHeader) {
      throw new Error('GitHub authentication required. Please set up GitHub credentials or token.');
    }
    const token = authHeader.replace('token ', '');

    // Fetch repository content with retries
    for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
      try {
        console.log(`Fetching repository content (attempt ${attempt}/${MAX_RETRIES}):`, 
          repoIdentifier, `(branch: ${actualBranch})`);
          //@ts-ignore
        const formData = new FormData();
        
        // Include authentication in the repository URL
        const repoUrl = `https://${token}@github.com/${repoIdentifier}.git`;
        console.log("Repository URL (with auth):", repoUrl.replace(token, '***'));
        
        formData.append('url', repoUrl);
        formData.append('format', 'xml');
        formData.append('ref', actualBranch);
        
        const options = {
          removeComments: false,
          removeEmptyLines: true,
          showLineNumbers: false,
          fileSummary: true,
          directoryStructure: true,
          outputParsable: false,
          includePatterns: includePatterns.join(','),
          ignorePatterns: ignorePatterns.join(','),
        };
        
        formData.append('options', JSON.stringify(options));
        console.log("formdata",formData)
        
        // Log FormData contents (without exposing token)
        console.log("FormData contents:", {
          url: `https://***@github.com/${repoIdentifier}.git`,
          format: 'md',
          ref: actualBranch,
          options: JSON.stringify(options)
        });
        //@ts-ignore
        const response = await fetch('https://api.repomix.com/api/pack', {
          method: 'POST',
          headers: {
            accept: '*/*',
            'accept-language': 'en-GB,en-US;q=0.9,en;q=0.8',
            priority: 'u=1, i',
            Referer: 'https://repomix.com/',
            'Origin': 'https://repomix.com'
          },
          body: formData
        });

        if (!response.ok) {
          const errorText = await response.text();
          console.error('API Response:', {
            status: response.status,
            statusText: response.statusText,
            body: errorText
          });
          throw new Error(`Failed to fetch repository: ${response.statusText}\n${errorText}`);
        }

        const responseText = await response.text();
        try {
          // Try to parse as JSON to get metadata
          const responseJson = JSON.parse(responseText);
          const tokenCount = responseJson.metadata?.summary?.totalTokens;
          console.log(
            `Repository content token count (approximately): ${Math.round(tokenCount / 1000)}K tokens`
          );
          return { text: responseJson.content, tokenCount: tokenCount || 0 };
        } catch (error) {
          // If parsing fails, return the text without token count
          console.log(
            'Could not parse token count from response, proceeding without token information'
          );
          console.error('Parse error:', error);
          console.log('Response text:', responseText.substring(0, 200) + '...');
          return { text: responseText, tokenCount: 0 };
        }

      } catch (error) {
        if (attempt === MAX_RETRIES) {
          console.error('Error fetching repository content:', error);
          throw new Error(`Failed to fetch repository content: ${error instanceof Error ? error.message : 'Unknown error'}`);
        }
        const delay = INITIAL_RETRY_DELAY * Math.pow(2, attempt - 1);
        console.log(`Attempt ${attempt} failed, retrying in ${delay/1000}s...`);
        await new Promise(resolve => setTimeout(resolve, delay));
      }
    }

    throw new Error('Failed to fetch repository after all retries');
  } catch (error) {
    console.error('Error fetching repository context:', error);
    throw new Error(`Failed to fetch repository context: ${error instanceof Error ? error.message : 'Unknown error'}`);
  }
}

async function saveDocumentationToFile(content: string, reponame?: string): Promise<void> {
  try {
    // Use reponame if provided, otherwise use default name
    const filename = reponame ? `${reponame}-documentation.md` : 'documentation.md';
    
    // Create a new file in the workspace
    await vscode.workspace.fs.writeFile(
      vscode.Uri.file(vscode.workspace.rootPath + '/' + filename),
      Buffer.from(content, 'utf8')
    );
    
    console.log(`Documentation saved to ${filename}`);
    vscode.window.showInformationMessage(`Documentation saved to ${filename}`);
  } catch (error) {
    console.error('Error saving documentation:', error);
    throw new Error(`Failed to save documentation: ${error instanceof Error ? error.message : 'Unknown error'}`);
  }
}

export async function generateDocumentation(
  repoContext: RepoContext,
  options: DocGenerationOptions = {},
  apiKey: string,
  reponame?: string,
): Promise<DocResponse> {
  try {
    const model = options.model || 'gemini-2.5-pro-preview-05-06';    
    if (!apiKey) {
      throw new Error('GEMINI_API_KEY environment variable is not set');
    }

    const basePrompt = `
Focus on:
1. Repository purpose and "what is it" summary
2. Quick start: How to install and use the basic core features
3. Configuration options and how to configure the project
4. If multiple public packages exist:
   - Package summary & installation instructions
   - Detailed documentation of public APIs/interfaces
5. Dependencies and requirements
6. Advanced usage examples with code snippets
7. Project structure overview
8. Contributing guidelines (if available)`;



// Focus on:
// 1. Repository purpose and "what is it" summary
// 2. Quick start: How to install and use the basic core features of the project
// 3. Configuration options and how to configure the project for use (if applicable)
// 4. If a repository has multiple public packages perform all the following steps for every package:
// 5. Package summary & how to install / import it 
// 6. Detailed documentation of every public feature / API / interface
// 7. Dependencies and requirements
// 8. Advanced usage examples

    const prompt = options.customInstructions 
      ? `${basePrompt}\n\nAdditional Instructions:\n${options.customInstructions}`
      : basePrompt;

    console.log('Generating documentation using model:', model);
    console.log("prompt", prompt)
    //@ts-ignore
    const response = await fetch(
      `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`,
      {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          systemInstruction: {
            parts: [{
              text: 'Generate comprehensive, well-structured documentation in markdown format. Focus on accuracy and clarity.',
            }],
          },
          contents: [{
            role: 'user',
            parts: [
              { text: repoContext.text },
              { text: prompt }
            ],
          }],
          generationConfig: {
            maxOutputTokens: options.maxTokens || 4000,
            temperature: 0.7,
            topP: 0.8,
            topK: 40,
          },
        }),
      }
    );

    if (!response.ok) {
      throw new Error(`API error (${response.status}): ${await response.text()}`);
    }

    const data: any = await response.json();
    if (data.error) {
      throw new Error(`API error: ${JSON.stringify(data.error, null, 2)}`);
    }

    const generatedContent = data.candidates[0].content.parts[0].text;

    // Always save documentation to file, using reponame if provided
    await saveDocumentationToFile(generatedContent, reponame);

    return {
      content: generatedContent,
      model,
      status: 'success'
    };

  } catch (error) {
    console.error('Documentation generation error:', error);
    return {
      content: '',
      model: options.model || 'unknown',
      status: 'error',
      error: error instanceof Error ? error.message : 'Unknown error'
    };
  }
}

// Update the old function for backward compatibility
export const fetchGeminiDocResponse = async (repoContext: RepoContext, api_key: string, reponame?: string, ) => {
  const response = await generateDocumentation(repoContext, {}, api_key, reponame);
  if (response.status === 'error') {
    throw new Error(response.error);
  }
  return response.content;
};