import { getSimpleRelativePath } from './util';
async function resolveSmartPath(inputPath, allowedRoot) {
    if (!inputPath) {
        throw new Error("Input path is empty.");
    }

    const allowedRootAbs = path.resolve(allowedRoot);
    let finalPath;

    if (path.isAbsolute(inputPath)) {
        try {
            await fs.access(inputPath);
            finalPath = inputPath;
        } catch {
            throw new Error(`Absolute path "${inputPath}" does not exist.`);
        }
    } else {
        const directPath = path.resolve(allowedRootAbs, inputPath);

        try {
            await fs.access(directPath);
            finalPath = directPath;
        } catch {
            const baseName = path.basename(inputPath);
            const pattern = `**/${baseName.replace(/\\/g, '/')}`;
            const matches = await fg(pattern, {
                cwd: allowedRootAbs,
                absolute: true,
                onlyFiles: false,
            });

            if (matches.length === 0) {
                throw new Error(`"${inputPath}" not found inside allowed root.`);
            }

            finalPath = matches[0];
        }
    }

    // Normalize for cross-platform comparison
    const normalizedFinalPath = path.normalize(path.resolve(finalPath));
    const normalizedAllowedRoot = path.normalize(path.resolve(allowedRootAbs));

    // Capitalize drive letter on Windows for accurate comparison
    function normalizeDriveCase(p) {
        return process.platform === 'win32' && p.length >= 2 && p[1] === ':' 
            ? p[0].toUpperCase() + p.slice(1) 
            : p;
    }

    const safeFinalPath = normalizeDriveCase(normalizedFinalPath);

   

    return safeFinalPath;
}

function getWorkspaceRootPath(): string {
    let rootPath = vscode.workspace.workspaceFolders?.[0]?.uri.fsPath || "";
    
    if (process.platform === 'win32' && rootPath.length > 1) {
        rootPath = rootPath.charAt(0).toUpperCase() + rootPath.slice(1);
    }

    return rootPath;
}

class MCPClient {
    mcp;
    anthropic;
    transport = null;
    tools = [];
    history = [];
    
    async init(anthropicApiKey: string) {
        this.anthropic = new Anthropic({
            apiKey: anthropicApiKey,
        });
        this.mcp = new Client({ name: 'mcp-client-cli', version: '1.0.0' });
    }
    
    async connectToServer(command, args) {
        try {
            const rootpath = getWorkspaceRootPath();
            // Create a custom wrapper around StdioClientTransport
            class CustomStdioTransport extends StdioClientTransport {
                constructor(server) {
                    super({
                        command: server.command,
                        args: server.args,
                        env: "",
                        stderr: 'pipe',
                        cwd: rootpath,
                    });
                }
            }

            this.transport = new CustomStdioTransport({
                command,
                args
            });

            await this.mcp.connect(this.transport);
            const toolsResult = await this.mcp.listTools();
            this.tools = toolsResult.tools.map((tool) => ({
                name: tool.name,
                description: tool.description,
                input_schema: tool.inputSchema,
            }));
            console.log('Connected to server with tools:', this.tools.map(({ name }) => name));
        }
        catch (e) {
            console.error('Failed to connect to MCP server:', e);
            throw e;
        }
    }
    async callTool(toolName, toolArgs) {
        const rootpath = getWorkspaceRootPath();
        console.debug(`Calling MCP tool ${toolName} with args: ${JSON.stringify(toolArgs)}`);
        if (!this.mcp || !this.transport) {
            await this.connectToServer('npx', [
                '-y',
                '@modelcontextprotocol/server-filesystem',
                rootpath,
            ]);
        }
        try {
            const result = await this.mcp.callTool({
                name: toolName,
                arguments: toolArgs,
            });
            console.debug(`Tool ${toolName} result: ${JSON.stringify(result)}`);
            return result.content
                .map((c) => (c.type === 'text' ? c.text : ''))
                .join('\n') || 'No text content returned';
        }
        catch (error) {
            console.error(`Error calling tool ${toolName}:`, error);
            return `Error: ${error.message}`;
        }
    }
    async generateResponse(toolName, toolArgs, query) {
        try {
            const toolResult = await this.callTool(toolName, toolArgs);
            console.log(`Tool result: ${toolResult}`);
            return  toolResult;
        }
        catch (error) {
            return `Error: ${error.message}`;
        }
    }
   
    async executeQuery(toolName, toolArgs, query) {
        return await this.generateResponse(toolName, toolArgs, query);
    }
    async cleanup() {
        await this.mcp.close();
        this.transport = null;
    }
   
}

function formatToolResponse(toolName: string, result: any, filePath?: string) {
    try {
        // console.log("tool called formatToolResponse!");
        

        const rootpath = getWorkspaceRootPath();
              
            // console.log("formatToolResponse result", result);
            // console.log("formatToolResponse filePath", filePath);
            // console.log("formatToolResponse toolName", toolName);
            

        if (toolName === "read_file" && typeof result === 'string') {
            const ext = filePath?.split('.').pop() || '';
            const language = getLanguageFromExtension(ext);
            const updatedFilePath = getSimpleRelativePath(filePath, rootpath);
            const fileName = updatedFilePath.split(/[\\/]/).pop(); 
            const fullPath = path.join(rootpath, updatedFilePath);
            const content = `## ${filePath}\n\`\`\`${language}\n${result}\n\`\`\``;

            return {
                content,
                // path: [fileName],
                path: [fullPath]
            };
        }

        else if (toolName === "read_multiple_files" && typeof result === 'string') {
            const files = result.split("\n\n---\n");
      
            // console.log("formatToolResponse files", files);
            
            
            const formattedFiles = files.map(file => {
                const [rawPath, ...contentParts] = file.split(":\n");
                const contentText = contentParts.join("\n").trim();
                const ext = rawPath.split('.').pop() || '';
                const language = getLanguageFromExtension(ext);
                // create a full path 
                const fullPath = path.join(rootpath, rawPath.trim());
                const cleanPath = getSimpleRelativePath(rawPath.trim(), rootpath);
                // console.log("formatToolResponse cleanPath", cleanPath);
                // console.log("formatToolResponse fullPath", fullPath);
                // console.log("formatToolResponse rawPath", rawPath);
                // console.log("formatToolResponse rootpath", rootpath);

                

                return {
                    // path: cleanPath,
                    path: fullPath,
                    content: `## ${cleanPath}\n\`\`\`${language}\n${contentText}\n\`\`\``,
                };
            });

            return {
                content: formattedFiles.map(f => f.content).join("\n\n"),
                paths: formattedFiles.map(f => f.path),
            };
        }
        return result;

    } catch (error) {
        console.error('Error formatting tool response:', error);
        return null;
    }
}


function getLanguageFromExtension(ext: string): string {
    const languageMap: { [key: string]: string } = {
        'js': 'javascript',
        'jsx': 'jsx',
        'ts': 'typescript',
        'tsx': 'tsx',
        'py': 'python',
        'css': 'css',
        'scss': 'scss',
        'html': 'html',
        'json': 'json',
        'md': 'markdown',
        // Add more mappings as needed
    };
    return languageMap[ext.toLowerCase()] || ext.toLowerCase();
}

export async function localserver(toolName, toolArgs, query, panel?: vscode.WebviewPanel) {
    console.log("Local server started");
    

    const storedAuthToken = getStoreKey(AUTH_TOKEN);
    if (!storedAuthToken) {
        console.error("No auth token found");
        return "Error: Authentication required";
    }

    const currentUserProfile = await getUserProfile(storedAuthToken);
    const encryptedServiceKeys = await getServiceKeys(storedAuthToken);


    let anthropic_key = ""; 
    try {
        const decryptedData = decrypt(currentUserProfile.id, encryptedServiceKeys);
        const keys_data_obj = JSON.parse(decryptedData); 
        anthropic_key = keys_data_obj.ANTHROPIC_API_KEY; 
    
    } catch (error) {
        console.error("Failed to decrypt service keys:", error);
        return "Error: Failed to decrypt service keys";
    }

    if (!anthropic_key) {
        console.error("No Anthropic API key found");
        return "Error: Anthropic API key not found";
    }

    const mcpClient = new MCPClient();
    try {
        await mcpClient.init(anthropic_key);
        let workspaceRootPath = getWorkspaceRootPath()
        console.log("Workspace root path:", workspaceRootPath);
        await mcpClient.connectToServer('npx', [
            '-y',
            '@modelcontextprotocol/server-filesystem',
            workspaceRootPath,
        ]);

        if (toolName === "read_file" || toolName === "list_directory") {
            console.log("tool args path", toolArgs.path || toolArgs.file_path);
            const resolvedPath = await resolveSmartPath(toolArgs.path || toolArgs.file_path, workspaceRootPath);
            if (toolArgs.path) {
                toolArgs.path = resolvedPath;
            } else {
                toolArgs.file_path = resolvedPath;
            }
        } else if (toolName === "get_file_info") {
            console.log("tool args.path", toolArgs.path);
            toolArgs.path = await resolveSmartPath(toolArgs.file_path, workspaceRootPath);
        }

        // Execute the query to get the result
        console.log("Resolved path:", toolArgs.path, toolArgs);
        const result = await mcpClient.executeQuery(toolName, toolArgs, query);
        console.log(`Result from local server: ${result}`);
        const formattedResult = formatToolResponse(toolName, result, toolArgs.path || toolArgs.file_path);
        

        // Send the response
        if (panel) {
            panel.webview.postMessage({
                command: 'file_system_res',
                data: formattedResult,
            });
        }
        
        return formattedResult;
    } catch (error) {
        console.error('Local server error:', error);
        if (panel) {
            panel.webview.postMessage({
                command: 'file_system_res_error',
                data: `Error: ${error.message}`,
            });
        }
        return `Error: ${error.message}`;
    } finally {
        await mcpClient.cleanup();
    }
}

