import { exec } from 'child_process';
import * as vscode from 'vscode';
import * as path from "path";
const fs = require("fs");
import { getGitHubHeaders, getGitHubToken, isGitHubCliAvailable } from './githubAuth';
//@ts-nocheck
export function detectTechStack(repoPath: string): string {
  // Check for common files for tech stack detection
  if (fs.existsSync(path.join(repoPath, 'package.json'))) {
    return 'node';
  } else if (fs.existsSync(path.join(repoPath, 'requirements.txt')) || fs.existsSync(path.join(repoPath, 'setup.py'))) {
    return 'python';
  } else if (fs.existsSync(path.join(repoPath, 'pom.xml'))) {
    return 'java';
  } else {
    return 'generic';
  }
}

export async function handleGitInitAndPush(parameter: {
  repo_name: string;
  root_dir: string;
  remote_url?: string
}): Promise<{ status: string; repo_name?: string; repo_url?: string; message?: string; error?: string }> {
  let { repo_name, root_dir, remote_url } = parameter;
  let repoData: any = null;

  // If repo_name is empty, get the last folder from root_dir.
  if (!repo_name || repo_name.trim() === "") {
    repo_name = path.basename(root_dir);
    console.log("Repo name set from root directory:", repo_name);
  }
  console.log("Initializing Git Repository with parameters:", parameter);

  if (!root_dir || root_dir.trim() === "") {
    if (vscode.workspace.workspaceFolders && vscode.workspace.workspaceFolders.length > 0) {
      root_dir = vscode.workspace.workspaceFolders[0].uri.fsPath;
    } else {
      console.error("Error: No root directory available.");
      return { status: 'error', error: 'No root directory available for repository initialization.' };
    }
  }

  // We'll use root_dir as repoPath; if you want to create a subfolder for the repo, uncomment the following line:
  // repoPath = path.join(root_dir, repo_name);
  let repoPath = root_dir;
  if (!fs.existsSync(repoPath)) {
    try {
      fs.mkdirSync(repoPath);
      console.log("Created repository directory at:", repoPath);
    } catch (err: any) {
      console.error("Error creating repository directory:", err.message);
      return { status: 'error', error: 'Failed to create repository directory: ' + err.message };
    }
  }

  // Automatically detect tech stack from repository contents
  const detectedTechStack = detectTechStack(repoPath);
  console.log("Detected tech stack:", detectedTechStack);

  const token = getGitHubToken();
  if (!token) {
    console.error("GitHub authentication failed.");
    return { status: 'error', error: 'GitHub authentication failed. Please login with GitHub CLI or set a valid token.' };
  }
  console.log("GitHub token obtained successfully.");

  function runCommand(command: string): Promise<string> {
    console.log(`Executing: ${command}\nWorking directory: ${repoPath}`);
    return new Promise((resolve, reject) => {
      exec(command, { cwd: repoPath }, (error, stdout, stderr) => {
        if (error) {
          console.error(`Error running command "${command}":`, stderr || error.message);
          reject(stderr || error.message);
        } else {
          console.log(`Output of "${command}":`, stdout);
          resolve(stdout);
        }
      });
    });
  }

  try {
    // Initialize Git repository and set branch to main
    console.log("Initializing Git in:", repoPath);
    await runCommand("git init");
    await runCommand("git branch -M main");

    // Check for .gitignore; if missing, create one with content based on detected tech stack.
    const gitignorePath = path.join(repoPath, ".gitignore");
    if (!fs.existsSync(gitignorePath)) {
      console.log(".gitignore not found. Creating one...");
      let gitignoreContent = "";
      switch (detectedTechStack) {
        case 'node':
          gitignoreContent = `node_modules/
dist/
.env
`;
          break;
        case 'python':
          gitignoreContent = `__pycache__/
*.pyc
env/
`;
          break;
        case 'java':
          gitignoreContent = `target/
*.class
`;
          break;
        default:
          gitignoreContent = `node_modules/
dist/
.env
`;
          break;
      }
      fs.writeFileSync(gitignorePath, gitignoreContent);
      console.log(".gitignore created with content:", gitignoreContent);
    } else {
      console.log(".gitignore already exists.");
    }

    console.log("Repo contents before adding files:", fs.readdirSync(repoPath));

    // Stage and commit files
    await runCommand("git add --all");
    await runCommand("git status");
    await runCommand(`git commit --allow-empty -m "Initial commit"`);
    await runCommand("git log -1");

    // Set remote and push
    if (remote_url && remote_url.trim() !== "") {
      console.log("Using provided remote URL:", remote_url);
      const headers = getGitHubHeaders();
      const authToken = headers.Authorization?.replace('token ', '') || headers.Authorization?.replace('Bearer ', '');
      const urlWithoutProtocol = remote_url.replace(/^https:\/\//, '');
      const authRemoteUrl = `https://${authToken}@${urlWithoutProtocol}`;
      try { await runCommand("git remote remove origin"); } catch (e) { console.warn("No existing remote origin to remove."); }
      await runCommand(`git remote add origin "${authRemoteUrl}"`);
      console.log("Set remote origin to:", authRemoteUrl);
      await runCommand("git push -u origin main");
    } else {
      console.log("No remote URL provided. Creating repository on GitHub...");
      if (isGitHubCliAvailable()) {
        const createRepoCommand = `gh repo create ${repo_name} --public --confirm --source="${repoPath}" --push`;
        console.log("Executing GitHub CLI command:", createRepoCommand);
        await runCommand(createRepoCommand);
      } else {
        const apiUrl = "https://api.github.com/user/repos";
        const requestBody = { name: repo_name, private: false };
        console.log("Creating repo via GitHub API:", apiUrl);
        //@ts-ignore
        const response = await fetch(apiUrl, {
          method: "POST",
          headers: {
            "Authorization": `token ${token}`,
            "Content-Type": "application/json",
            "Accept": "application/vnd.github.v3+json"
          },
          body: JSON.stringify(requestBody)
        });
        if (!response.ok) {
          const errText = await response.text();
          console.error("GitHub API error:", errText);
          throw new Error(`GitHub API error: ${errText}`);
        }
        repoData = await response.json();
        console.log("GitHub repository created successfully:", repoData.clone_url);
        const urlWithoutProtocol = repoData.clone_url.replace(/^https:\/\//, '');
        const authRemoteUrl = `https://${token}@${urlWithoutProtocol}`;
        try { await runCommand("git remote remove origin"); } catch (e) { console.warn("No existing remote origin to remove."); }
        await runCommand(`git remote add origin "${authRemoteUrl}"`);
        await runCommand("git push -u origin main");
      }
    }

    console.log("Repository initialized and pushed successfully.");
    return {
      status: 'success',
      repo_name: repo_name && repo_name.trim() !== "" ? repo_name : path.basename(root_dir),
      repo_url: remote_url || repoData?.clone_url,
      message: "Repository initialized and pushed successfully."
    };
  } catch (error: any) {
    console.error("Error during Git initialization or push:", error);
    return { status: 'error', error: error.toString() };
  }
}




export async function handleGitInit(parameter: { repo_name: string; root_dir: string }): Promise<{ status: string; repo_name?: string; message?: string; error?: string }> {
  console.log("Inside handleGitInit :", parameter);

  let { repo_name, root_dir } = parameter;

  // If no root_dir is provided, get the first workspace folder.
  if (!root_dir || root_dir.trim() === "") {
    if (vscode.workspace.workspaceFolders && vscode.workspace.workspaceFolders.length > 0) {
      root_dir = vscode.workspace.workspaceFolders[0].uri.fsPath;
    } else {
      return { status: 'error', error: 'No root directory available for repository initialization.' };
    }
  }

  // Determine the repository path.
  // If a repo_name is provided, use it; otherwise, use the root directory.
  let repoPath = root_dir;
  if (repo_name && repo_name.trim() !== "") {
    repoPath = path.join(root_dir, repo_name);
    // Create the directory if it doesn't exist.
    if (!fs.existsSync(repoPath)) {
      try {
        fs.mkdirSync(repoPath);
      } catch (err: any) {
        return { status: 'error', error: 'Failed to create repository directory: ' + err.message };
      }
    }
  }

  // Execute the "git init" command in the determined directory.
  return new Promise((resolve) => {
    exec("git init", { cwd: repoPath }, (error, stdout, stderr) => {
      if (error) {
        resolve({ status: 'error', error: stderr || error.message });
      } else {
        resolve({
          status: 'success',
          repo_name: repo_name && repo_name.trim() !== "" ? repo_name : path.basename(root_dir),
          message: stdout
        });
      }
    });
  });
}