// serverManager.ts
import * as cp from 'child_process';
import { isString, result } from 'lodash';
import * as vscode from 'vscode';
import { getStoreKey } from './StorageService';
import { AUTH_TOKEN } from './Constants';
import { getUserProfile } from './CommonServices';
import { encrypt } from './EncryptDecrypt';

interface ServerParams {
  command: string;
  args: string[];
  env: { [key: string]: string };
}

const runningServers: { [key: string]: cp.ChildProcess } = {};
const toolResponses: { [key: string]: any[] } = {};
let currentRpcId = 1;
const outputBuffers: { [key: string]: string } = {};
const startupTimestamps: { [key: string]: number } = {};

export async  function launchServer(serverId: string, params: ServerParams, panel?: vscode.WebviewPanel): Promise<void> {
  // console.log(`🛠️ DEBUG: launchServer called with serverId=${serverId}`);

  if (runningServers[serverId]) {
    // console.log(`🛠️ DEBUG: Server ${serverId} already running. Stopping first.`);
    stopServer(serverId);
    // return;
  }

  if (params.command?.trim()?.startsWith('npx') && !params.args?.includes('-y')) {
    params.args.unshift('-y');
  }
  const hasValidCommand = params.command && params.command?.trim();
  const hasValidArgs = params.args && params.args.some(arg => !arg.startsWith('-'));
  
  if (!hasValidCommand || !hasValidArgs) {
    console.error(`[${serverId}] ❌ launchServer failed: Invalid command or missing script name.`);
    if (panel) {
      panel.webview.postMessage({
        type: 'serverError',
        serverId,
        error: 'Invalid command or missing script name to launch server.',
      });
    }
    return;
  }
  
  const env = { ...process.env, ...params.env };
  // console.log(`🛠️ DEBUG: Spawning process: ${params.command} ${params.args.join(' ')}`);

  const proc = cp.spawn(params.command, params.args, {
    env,
    shell: true,
    cwd: vscode.workspace.workspaceFolders?.[0]?.uri.fsPath ?? undefined,
    stdio: ['pipe', 'pipe', 'pipe'],
  });

  runningServers[serverId] = proc;
  outputBuffers[serverId] = '';

  // console.log(`[${serverId}] 🛠️ DEBUG: Process spawned.`);

  proc.stdout?.on('data', (data) => {
    // console.log(`🛠️ DEBUG: [${serverId}] stdout event triggered`);
    handleData(serverId, data.toString(), proc.stdin, panel);
  });

 
  proc.stderr?.on('data', (data) => {
    // console.log(`[${serverId}] 🛠️ DEBUG: stderr event triggered`);
    handleStderr(serverId, data.toString(), panel);
  });

  proc.on('error', (err) => {
    console.error(`[${serverId}] Failed to start process:`, err);
    if (panel) {
      panel.webview.postMessage({
        type: 'serverError',
        serverId,
        error: err.message,
      });
    }
    stopServer(serverId);
  });

  proc.on('exit', (code) => {
    // console.log(`[${serverId}] 🛠️ DEBUG: Process exited with code ${code}`);
    delete runningServers[serverId];
    delete toolResponses[serverId];
    delete outputBuffers[serverId];
  });

  setTimeout(() => {
    // console.log(`🛠️ DEBUG: [${serverId}] Timeout finished, sending list_tools`);
    sendListToolsRequest(proc.stdin, serverId);
  }, 2000);

  return ;
}

async function handleData(serverId: string, chunk: string, stdin?: cp.ChildProcess['stdin'], panel?: vscode.WebviewPanel) {
  // console.log(`🛠️ DEBUG: [${serverId}] handleData called. Chunk length: ${chunk.length}`);

  outputBuffers[serverId] += chunk;
  const lines = outputBuffers[serverId].split('\n');
  outputBuffers[serverId] = lines.pop() ?? '';

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed) continue;

    const isLikelyJson = (trimmed.startsWith('{') && trimmed.endsWith('}')) ||
                         (trimmed.startsWith('[') && trimmed.endsWith(']'));
    if (!isLikelyJson) {
      console.warn(`[${serverId}] 🛠️ DEBUG: Skipping non-JSON line:`, trimmed);
      continue;
    }

    // console.log(`[${serverId}] 🛠️ DEBUG: Attempting to parse JSON line.`);

    try {
      const json = JSON.parse(trimmed);
      // console.log(`[${serverId}] 🛠️ DEBUG: JSON parsed successfully.`);

      if (json.jsonrpc === '2.0' && json.result?.tools) {
        // console.log(`[${serverId}] 🛠️ DEBUG: Detected tools in response. \n ${json.result}`);

        stopAllServers();
        stopServer(serverId);
        // console.log(`[${serverId}] 🛠️ DEBUG: Stopping server after successful tools fetch.`);
        toolResponses[serverId] = json.result.tools;

        if (panel) {
          // console.log(`[${serverId}] 🛠️ DEBUG: Panel exists. Preparing to send encrypted tools.`);

          const authToken = getStoreKey(AUTH_TOKEN);
          if (!authToken) {
            vscode.window.showInformationMessage("Authentication required");
            console.log(`[${serverId}] 🛠️ DEBUG: No auth token found.`);
            return;
          }

          console.log(`[${serverId}] 🛠️ DEBUG: Auth token found, fetching user profile.`);

          const authUser = await getUserProfile(authToken);
          // console.log(`[${serverId}] 🛠️ DEBUG: Fetched user profile.`);

          const toolSchemaPayload = {
            "server_name": serverId,
            "tools": json.result?.tools || []
          }
          const encryptedResult = encrypt(
            authUser.id,
            JSON.stringify(toolSchemaPayload)
          );
          // console.log(`[${serverId}] 🛠️ DEBUG: Encrypted result created for :`, json.result );

          panel.webview.postMessage({
            type: 'mcpTools',
            serverId,
            result: encryptedResult,
          });
          // console.log(`[${serverId}] 🛠️ DEBUG: Posted encrypted tools to webview.`);
        }
     
      }

    } catch (err) {
      console.error(`[${serverId}] 🛠️ DEBUG: Failed to parse JSON:`, trimmed, err);
    }

    if (trimmed.includes('MCP Server running on stdio')) {
      // console.log(`[${serverId}] 🛠️ DEBUG: Detected server startup message, sending list_tools again.`);
      sendListToolsRequest(stdin, serverId);
    }
  }
}

function handleStderr(serverId: string, stderrText: string, panel?: vscode.WebviewPanel) {
  // console.log(`[${serverId}] 🛠️ DEBUG: STDERR content:`, stderrText);

  const startupTime = startupTimestamps[serverId] ?? 0;
  const isEarlyStartup = false || (Date.now() - startupTime) < 5000; 

  // console.log(`[${serverId}] 🛠️ DEBUG: isEarlyStartup: ${isEarlyStartup}`);
  const isStartupFailure =
    stderrText.includes('npm ERR!') ||
    stderrText.includes('404') ||
    stderrText.toLowerCase().includes('not found');

  if ((isEarlyStartup || isStartupFailure) && panel) {
    // console.log(`[${serverId}] 🛠️ DEBUG: Detected early startup error, notifying webview`);
    panel.webview.postMessage({
      type: 'serverError',
      serverId,
      error: stderrText,
    });
    stopAllServers();
    stopServer(serverId);
  }
}

function sendListToolsRequest(stdin: cp.ChildProcess['stdin'] | null | undefined, serverId: string) {
  if (!stdin) {
    console.log(`[${serverId}] 🛠️ DEBUG: stdin is null, cannot send list_tools.`);
    return;
  }

  const request = {
    id: currentRpcId++,
    jsonrpc: '2.0',
    method: 'tools/list',
    params: {},
  };

  const message = JSON.stringify(request) + '\n';
  console.log(`[${serverId}] 🛠️ DEBUG: ➡️ Sending tools/list request ${message}`);

  stdin.write(message, (err) => {
    if (err && isString(err)  && err !== 'Cannot call write after a stream was destroyed') {
      console.error(`[${serverId}] 🛠️ DEBUG: ❌ Failed to write tools/list request:`, err);
    } else {
      // console.log(`[${serverId}] 🛠️ DEBUG: ✅ Successfully wrote tools/list request.`);
    }
  });
}


export function getToolsFromServer(serverId: string): any[] {
  return toolResponses[serverId] || [];
}

export function stopServer(serverId: string) {
  const proc = runningServers[serverId];
  if (proc) {
    proc.kill(); // kill the process
  }
  delete runningServers[serverId];
  delete toolResponses[serverId];
  delete outputBuffers[serverId];
  // vscode.window.showInformationMessage(`Stopped server: ${serverId}`);
}


export async function stopAllServers(): Promise<void> {
  Object.keys(runningServers).forEach((id) => {
    // console.log(`🛠️ DEBUG: Stopping/killing00 server with ID: ${id}`);
    
    runningServers[id].kill();
    delete runningServers[id];
  });

  await new Promise((resolve) => {
    setTimeout(() => {
      resolve(true);
    }, 500);
  });
}

