export async function getSemanticSearchResponse_gemini(
  user_message: string,
  history_context = "",
  file_paths: any,
  root = "",
  is_error = false,
  error_message = "",
  signal: any,
  gemini_key: string
) {
  console.log(history_context, "gemini - history_from_semantic");
  try {
    const prompt = createSemanticSearchResponse(
      user_message,
      history_context,
      file_paths,
      root,
      is_error,
      error_message,
      "gemini"
    );
    const model = "gemini-2.5-pro-preview-05-06";

    console.log("history_from_semantic- Using Gemini model:", model);
    const response = await fetch(
      `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${gemini_key}`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        signal, // Pass through the abort signal
        body: JSON.stringify({
          systemInstruction: {
            parts: [
              {
                text: "You are a semantic search assistant that extracts and returns JSON responses based on conversation history.",
              },
            ],
          },
          contents: [
            {
              role: "user",
              parts: [{ text: prompt }],
            },
          ],
          generationConfig: {
            maxOutputTokens: 8000,
            temperature: 0,
          },
        }),
      }
    );

    if (!response.ok) {
      throw new Error(
        `Gemini API error (${response.status}): ${await response.text()}`
      );
    }

    const data = await response.json();
    if (data.error) {
      throw new Error(
        `Gemini API error: ${JSON.stringify(data.error, null, 2)}`
      );
    }

    // Return the generated content
    console.log("history_from_semantic- gemini semantic found");
    return data.candidates[0].content.parts[0].text;
  } catch (error) {
    if (error.name === "AbortError") {
      throw error;
    }
    throw new Error(`Gemini API error: ${error.message}`);
  }
}

export async function getAnthropicSearchResponse_sonnet(
  user_message: string,
  history_context = "",
  file_paths: any,
  root = "",
  is_error = false,
  error_message = "",
  signal: any,
  anthropic_key: string
) {
  console.log(history_context, "claude-sonnet - history_from_semantic");

  try {
    const prompt = createSemanticSearchResponse(
      user_message,
      history_context,
      file_paths,
      root,
      is_error,
      error_message,
      "anthropic"
    );

    const model = "claude-3-5-sonnet-20241022";

    console.log("history_from_semantic- Using Claude model:", model);
    const response = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: {
        "x-api-key": anthropic_key,
        "anthropic-version": "2023-06-01",
        "content-type": "application/json",
      },
      signal,
      body: JSON.stringify({
        model: model,
        max_tokens: 8000,
        messages: [
          {
            role: "user",
            content: prompt,
          },
        ],
      }),
    });

    if (!response.ok) {
      throw new Error(
        `Claude API error (${response.status}): ${await response.text()}`
      );
    }

    const data = await response.json();
    if (data.error) {
      throw new Error(
        `Claude API error: ${JSON.stringify(data.error, null, 2)}`
      );
    }

    // Return the generated content
    console.log("history_from_semantic- claude semantic found");
    return data.content[0].text;
  } catch (error) {
    if (error.name === "AbortError") {
      throw error;
    }
    throw new Error(`Claude API error: ${error.message}`);
  }
}

