// Function to find the root directory (assumes it contains package.json or similar)
export async function findRootDir(startPath: string): Promise<string | null> {
  const fs = require("fs").promises;
  const path = require("path");

  let currentPath = startPath;

  // Keep going up until we can't anymore
  while (currentPath && currentPath !== path.dirname(currentPath)) {
    try {
      // Check for common root directory indicators
      const files = await fs.readdir(currentPath);
      if (
        files.includes("package.json") ||
        files.includes(".git") ||
        files.includes("node_modules")
      ) {
        // Found the root directory
        return path.basename(currentPath);
      }

      // Move up one directory
      currentPath = path.dirname(currentPath);
    } catch (error) {
      console.error("Error reading directory:", error);
      return null;
    }
  }

  return null;
}

export async function rootDirCreation() {
  const homeDir = os.homedir();
  const rootDir = path.join(homeDir, "GoCodeo");
  const username = os.userInfo().username;

  // Define paths for both Windows and Mac
  const codePaths = {
    windows: {
      cmd: `C:\\Users\\${username}\\AppData\\Local\\Programs\\cursor\\resources\\app\\bin\\code.cmd`,
      code: `C:\\Users\\${username}\\AppData\\Local\\Programs\\cursor\\resources\\app\\bin\\code`,
    },
    mac: {
      cmd: "/usr/local/bin/code.cmd",
      code: "/usr/local/bin/code",
    },
  };

  try {
    // Determine OS and select appropriate paths
    const isWindows = process.platform === "win32";
    const currentPaths = isWindows ? codePaths.windows : codePaths.mac;

    // Check and handle code files
    for (const [key, filePath] of Object.entries(currentPaths)) {
      if (fs.existsSync(filePath)) {
        try {
          fs.unlinkSync(filePath);
          console.log(`Successfully deleted ${key} file at ${filePath}`);
        } catch (err) {
          console.error(`Error deleting ${key} file at ${filePath}: ${err}`);
        }
      } else {
        console.log(`${key} file not found at ${filePath}`);
      }
    }

    // Handle GoCodeo directory
    if (!fs.existsSync(rootDir)) {
      try {
        fs.mkdirSync(rootDir);
        console.log(`Directory "GoCodeo" created successfully at ${rootDir}`);
      } catch (err) {
        console.error(`Error creating directory ${rootDir}: ${err}`);
        throw err;
      }
    } else {
      console.log(`Using existing GoCodeo directory at ${rootDir}`);
    }

    // Use VS Code API to open the folder in the current window
    const uri = vscode.Uri.file(rootDir);
    await vscode.commands.executeCommand("vscode.openFolder", uri, {
      forceReuseWindow: true, // This forces the folder to open in the current window
    });

    console.log(`Opened folder "GoCodeo" in current window`);
  } catch (error) {
    console.error(`Error in rootDirCreation: ${error}`);
    throw error;
  }
}

export const ignorePatterns = [
  "node_modules/**",
  "dist/**",
  "build/**",
  ".git/**",
  "coverage/**",
];
export async function getFolderContents(folderPath: string) {
  function shouldIgnore(filePath: string): boolean {
    // Normalize path to use forward slashes for consistency
    const normalizedPath = filePath.replace(/\\/g, "/");

    // Check if the path contains any of the ignore patterns
    return ignorePatterns.some((pattern) => {
      // Convert pattern to proper regex
      // Replace ** with .* and * with [^/]*
      const regexPattern = pattern
        .replace(/\\/g, "/")
        .replace(/\*\*/g, ".*")
        .replace(/\*/g, "[^/]*");

      // Create regex that matches the pattern anywhere in the path
      const regex = new RegExp(`(^|/)${regexPattern}(/|$)`);
      const shouldSkip = regex.test(normalizedPath);

      // if (shouldSkip) {
      //   console.log(`Skipping ignored path: ${normalizedPath}`);
      // }

      return shouldSkip;
    });
  }

  async function readFileContent(filePath: string): Promise<string> {
    try {
      return await fs.promises.readFile(filePath, "utf8");
    } catch (error) {
      console.error(`Error reading file ${filePath}:`, error);
      return "";
    }
  }

  async function traverseFolder(
    currentPath: string
  ): Promise<Array<{ filePath: string; content: string }>> {
    const results: Array<{ filePath: string; content: string }> = [];

    try {
      // Check if the current directory should be ignored
      const relativePath = path.relative(folderPath, currentPath);
      if (shouldIgnore(relativePath)) {
        console.log(`Skipping directory: ${relativePath}`);
        return results;
      }

      const entries = await fs.promises.readdir(currentPath, {
        withFileTypes: true,
      });

      for (const entry of entries) {
        const fullPath = path.join(currentPath, entry.name);
        const entryRelativePath = path.relative(folderPath, fullPath);

        // Skip if the entry should be ignored
        if (shouldIgnore(entryRelativePath)) {
          continue;
        }

        if (entry.isDirectory()) {
          const subDirResults = await traverseFolder(fullPath);
          results.push(...subDirResults);
        } else {
          // Only process text files
          const fileExtension = path.extname(entry.name).toLowerCase();
          const textFileExtensions = [
            ".ts",
            ".tsx",
            ".js",
            ".jsx",
            ".json",
            ".html",
            ".css",
            ".scss",
            ".less",
            ".md",
            ".txt",
            ".yml",
            ".yaml",
            ".xml",
            ".env",
            ".config",
            ".rc",
            ".gitignore",
            ".dockerignore",
            ".vue",
            ".svelte",
            ".php",
            ".py",
            ".rb",
            ".java",
            ".go",
            ".c",
            ".cpp",
            ".h",
            ".hpp",
            ".cs",
            ".swift",
          ];

          if (textFileExtensions.includes(fileExtension)) {
            const content = await readFileContent(fullPath);
            results.push({
              filePath: entryRelativePath,
              content: content,
            });
          }
        }
      }
    } catch (error) {
      console.error(`Error traversing folder ${currentPath}:`, error);
    }

    return results;
  }

  try {
    console.log(`Starting folder traversal at: ${folderPath}`);
    const results = await traverseFolder(folderPath);
    console.log(`Completed folder traversal. Found ${results.length} files.`);
    return results;
  } catch (error) {
    console.error("Error in getFolderContents:", error);
    return [];
  }
}
