export async function getSemanticFolderContext(
  fileContents: Array<{ filePath: string; content: string }>,
  featureRequest: string,
  user_input: string,
  gemini_key: string,
  signal?: AbortSignal
) {
  const createFolderContextPrompt = (
    files: Array<{ filePath: string; content: string }>,
    request: string,
    user_input: string
  ) => {
    return `You are an expert code analyzer that ONLY IDENTIFIES and RETRIEVES relevant code sections from files. DO NOT modify, fix, or suggest improvements to the code.
  
  FEATURE REQUEST/user's intention: "${request}"
  USER INSTRUCTION: "${user_input}"
  
  AVAILABLE FILES:
  ${files.map((f) => `- ${f.filePath}`).join("\n")}
  
  YOUR TASK:
  1. Analyze the files to find relevant code sections that match the user's request:
     - Look for code patterns related to the request
     - Identify relevant file types and sections
     - Find related code sections within each file
     - Group ALL relevant sections from the same file together
  
  2. For each relevant file:
     - Find ALL code sections that relate to the request
     - Include complete logical blocks and their context
     - Keep all related code sections together
     - DO NOT modify or suggest improvements to the code
  
  3. Extract ONLY existing code that:
     - Directly relates to the feature request
     - Shows current implementation
     - Demonstrates existing patterns
     - Is relevant to user's needs
  
  RETRIEVAL REQUIREMENTS:
  1. Code Selection:
     - Include COMPLETE code blocks
     - Keep ALL related sections from same file together
     - Maintain EXACT code as it exists
     - DO NOT split related code from same file
  
  2. Relevance Assessment:
     - Explain why the file/code is relevant
     - Describe how sections relate to request
     - Focus on EXISTING code patterns
     - DO NOT suggest improvements
  
  FILE CONTENTS:
  ${files
    .map(
      (f) => `
  === ${f.filePath} ===
  ${f.content}
  `
    )
    .join("\n")}
  
  RESPONSE FORMAT:
  {
      "relevant_folder_context": [
          {
              "file_path": "<file path>",
              "relevant_content_file": "<ALL relevant existing code sections from this file, grouped together>",
              "relevance_reason": "<why this code is relevant to the request>"
          }
      ]
      
  }
  
  CRITICAL REQUIREMENTS:
  1. ONLY retrieve existing code - DO NOT modify it
  2. Group ALL relevant sections from same file together
  3. Keep code formatting exactly as is
  4. Include complete logical blocks
  5. Focus on finding relevant code
  6. Return valid JSON only
  
  VALIDATION:
  1. Verify all file paths exist in input
  2. Check that code is exactly as in source
  3. Ensure all related code from same file is grouped
  4. Validate JSON structure
  5. NO code improvements or fixes
  6. NO splitting of related code from same file
  
  JSON FORMATTING REQUIREMENTS:
1. String Escaping Rules:
   - Use \\" for double quotes within strings
   - Use \\\\ for backslashes
   - Use \\n for newlines
   - Use \\t for tabs
   - Use \\r for carriage returns
   - Use \\b for backspace
   - Use \\f for form feed

2. Code Content Formatting:
   - When including code snippets in "relevant_content_file":
     - Escape all quotes: "my_string" becomes \\"my_string\\"
     - Escape all backslashes: "\\path" becomes \\"\\\\path\\"
     - Convert all newlines to \\n
     - Remove any unescaped special characters

3. JSON Structure:
   - No trailing commas in arrays or objects
   - All property names must be in double quotes
   - All string values must be in double quotes
   - Arrays must end with ] not ],
   - Objects must end with } not },

4. Example Format:
   {
     "relevant_folder_context": [
       {
         "file_path": "path/to/file.py",
         "relevant_content_file": "def my_function():\\n    print(\\"Hello\\")\\n",
         "relevance_reason": "This file contains the main function"
       }
     ]
   }

5. Validation Steps:
   - Verify all strings are properly escaped
   - Check for balanced quotes and brackets
   - Ensure no trailing commas
   - Confirm all special characters are escaped
   - Test that output can be parsed as valid JSON

Remember: The entire response must be valid JSON that can be parsed without errors.
  `;
  };

  try {
    // Use Gemini model first
    const prompt = createFolderContextPrompt(
      fileContents,
      featureRequest,
      user_input
    );
    const model = "gemini-2.0-flash";

    console.log("folder_context: Using Gemini model:", model);
    const response = await fetch(
      `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${gemini_key}`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        signal,
        body: JSON.stringify({
          systemInstruction: {
            parts: [
              {
                text: "You are a code analysis expert that identifies relevant code sections from files based on feature requests.",
              },
            ],
          },
          contents: [
            {
              role: "user",
              parts: [{ text: prompt }],
            },
          ],
          generationConfig: {
            maxOutputTokens: 8000,
            temperature: 0,
          },
        }),
      }
    );

    if (!response.ok) {
      throw new Error(
        `Gemini API error (${response.status}): ${await response.text()}`
      );
    }

    const data = await response.json();
    if (data.error) {
      throw new Error(
        `Gemini API error: ${JSON.stringify(data.error, null, 2)}`
      );
    }

    console.log("folder_context: gemini analysis complete");
    return data.candidates[0].content.parts[0].text;
  } catch (error) {
    if (error.name === "AbortError") {
      throw error;
    }
    console.error("Error in getSemanticFolderContext:", error);
    return JSON.stringify({
      relevant_folder_context: [],
      relevant_files: [],
    });
  }
}

export function getSimpleRelativePath(
  fullPath: string,
  rootPath: string
): string {
  const normalizeCase = (p: string) =>
    process.platform === "win32" ? p.toLowerCase() : p;

  const normalizedFullPath = normalizeCase(fullPath);
  const normalizedRootPath = normalizeCase(rootPath);

  if (normalizedFullPath.startsWith(normalizedRootPath)) {
    const relativePath = fullPath.slice(rootPath.length);
    return relativePath.replace(/^[/\\]+/, "");
  }

  return fullPath.split(/[/\\]/).pop() || fullPath;
}
