  async findRelevantHistoryIndices(historyEmbeddings: EmbeddingResult[], messageEmbedding: EmbeddingResult[],  topN: number = 3): Promise<Record<number, number>> {
    console.log(`[RELACE] Finding the top ${topN} relevant history indices...`, historyEmbeddings?.length, messageEmbedding?.length);
    if (!historyEmbeddings) {
      return [];
    }
    
    if (!messageEmbedding) {
      return [];
    }
    
    // Calculate similarities
    const similarityIndex: Record<number, number> = {};
    
    for (let i = 0; i < historyEmbeddings?.length; i++) {
      const similarity = this.cosineSimilarity(
        messageEmbedding[0].embedding,
        historyEmbeddings[i].embedding
      );
      // console.log(`Similarity between message and history ${i}: ${similarity.toFixed(4)}`);
      similarityIndex[historyEmbeddings[i].index] = similarity;
    }
    
    // change topindices to be list of index and similarity value . example: {0: 0.8, 1: 0.7, 2: 0.6}
    // console.log("[RELACE] Similarity index:", similarityIndex);

    // Sort the similarities in descending order
    const topIndices = Object.keys(similarityIndex)
      .map(Number)
      .sort((a, b) => similarityIndex[b] - similarityIndex[a])
      .slice(0, topN);
    
    // console.log("[RELACE] Top indices:", topIndices);
    const topSimilarityMap = topIndices.reduce<Record<number, number>>((acc, index) => {
      acc[index] = similarityIndex[index];
      return acc;
    }, {});

    // console.log("[RELACE] Top similarity map:", topSimilarityMap);
    
    // Return the relevant history items
    return topSimilarityMap;
  }
