import * as vscode from 'vscode';
import * as path from 'path';
import * as fs from 'fs';
import fetch from 'node-fetch';
import FormData from 'form-data';
import { FormDataEncoder } from 'form-data-encoder';
import { RelaceEmbeddingService } from './RelaceService';
import { Blob } from 'buffer';
import { Readable } from 'stream';
import { BASE_URL } from './Constants';

// Store indices in gocodeo/build_indices directory
const userDataPath = process.platform === "win32"
    ? process.env.APPDATA || path.join(process.env.USERPROFILE || "", "AppData", "Roaming")
    : path.join(process.env.HOME || "", ".config");
const INDICES_PATH = path.join(userDataPath, "gocodeo", "build_indices");
const HISTORY_PATH = path.join(userDataPath, "gocodeo", "build_sessions");

interface SearchResult {
    distance: number;
    index: number;
}

interface SearchResponse {
    results: SearchResult[];
}

interface ChunkMetadata {
    sessionId: string;
    chunkIndex: number;
    startIndex: number;
    endIndex: number;
    originalText: string;
    timestamp?: string;
}

export class EmbeddingService {
    private indicesPath: string;
    private embeddingService: RelaceEmbeddingService;
    private relaceKey: string;
    private context: vscode.ExtensionContext;

    constructor(relaceKey: string, context: vscode.ExtensionContext) {
        this.context = context;
        // Store indices in the build_indices directory
        this.indicesPath = INDICES_PATH;
        this.historyPath = HISTORY_PATH;
        this.relaceKey = relaceKey;
        // console.log("[RELACE]: Key: ", this.relaceKey);
        if (!fs.existsSync(this.indicesPath)) {
            fs.mkdirSync(this.indicesPath, { recursive: true });
        }
        this.embeddingService = new RelaceEmbeddingService(this.relaceKey);
    }

    private getIndexPath(sessionId: string): string {
        return path.join(this.indicesPath, `${sessionId}.index`);
    }

    private getHistoryPath(sessionId: string): string {
        return path.join(this.historyPath, `${sessionId}.json`);
    }

    private getMetadataPath(sessionId: string): string {
        return path.join(this.indicesPath, `${sessionId}_metadata.json`);
    }

    private async saveMetadata(sessionId: string, metadata: str): Promise<void> {
        const metadataPath = this.getMetadataPath(sessionId);
        await fs.promises.writeFile(metadataPath, metadata);
    }

    private async loadMetadata(sessionId: string): Promise<ChunkMetadata[]> {
        const metadataPath = this.getMetadataPath(sessionId);
        try {
            const data = await fs.promises.readFile(metadataPath, 'utf-8');
            return JSON.parse(data);
        } catch (error) {
            console.error('Error loading metadata:', error);
            return [];
        }
    }

    async createAndStoreIndex(texts: string[], sessionId: string, metadata?: str, authToken: string, userId: string): Promise<void> {
        try {
            // Get embeddings using relace
            const embeddings = await this.embeddingService.createEmbedding(texts, authToken, userId);

            console.log('[EMBEDDING] Got embeddings:', embeddings.length, 'chunks:', texts.length, 'session:', sessionId);

            const indexPath = this.getIndexPath(sessionId);
            const embeddingsJson = JSON.stringify(embeddings);
            await fs.promises.writeFile(indexPath, embeddingsJson, 'utf8');


            // Save metadata if provided
            if (metadata) {
                await this.saveMetadata(sessionId, metadata);
            }

            console.log(`Index and metadata saved for session ${sessionId}`);
        } catch (error) {
            console.error('Error creating index:', error);
            throw error;
        }
    }

    async searchIndex(sessionId: string, queryText: string, authToken: string, userId: string, topK: number = 3): Promise<{results: SearchResult[], metadata: ChunkMetadata[]}> {
        try {
            console.log('[EMBEDDING DEBUG] Starting search with:', { sessionId, queryText, topK });

            // Get query embedding
            // console.log('[EMBEDDING DEBUG] Getting query embedding...');


            const queryEmbedding = await this.embeddingService.createEmbedding([queryText], authToken, userId);
            console.log('[EMBEDDING DEBUG] Query embedding received, length:', queryEmbedding.length);

            // Get index file path and check if it exists
            const indexPath = this.getIndexPath(sessionId);
            const historyPath = this.getHistoryPath(sessionId);
            console.log('[EMBEDDING DEBUG] Index path:', indexPath, historyPath);

            if (!fs.existsSync(indexPath)) {
                console.error('[EMBEDDING DEBUG] No index found for session', sessionId);
                return {};
                // throw new Error(`No index found for session ${sessionId}`);
            }

            // Get file stats for debugging
            const stats = fs.statSync(indexPath);
            console.log('[EMBEDDING DEBUG] Index file stats:', {
                size: stats.size,
                created: stats.birthtime,
                modified: stats.mtime
            });

            // Create form data
            // console.log('[EMBEDDING DEBUG] Creating form data...');
            const formData = new FormData();

            // Read index file as a buffer and create a readable stream
            const indexFileBuffer = fs.readFileSync(indexPath);
            const historyFileBuffer = fs.readFileSync(historyPath);
            const indexFileString = indexFileBuffer.toString();

            // Parse string to JSON
            let history_embeddings = [];
            try {
            history_embeddings = JSON.parse(indexFileString);
            } catch (e) {
            console.error("Failed to parse JSON:", e);
            }

            let buildSession = {};
            try {
            buildSession = JSON.parse(historyFileBuffer.toString());
            } catch (e) {
            console.error("Failed to parse JSON:", e);
            }

            let build_history = buildSession?.buildHistory || [];
            // console.log('[EMBEDDING DEBUG] Build history:', build_history);

            console.log('[EMBEDDING DEBUG] Index file buffer size:', history_embeddings.length);
            const topIndexMap = await this.embeddingService.findRelevantHistoryIndices(history_embeddings, queryEmbedding, topK);

            console.log('[EMBEDDING DEBUG] Search topIndices:', topIndexMap);
            const topHistoryItems = Object.keys(topIndexMap)
            .map(Number)
            .map((index) => {
                const history_item = build_history[index];
                if (!history_item) {
                console.log('[EMBEDDING DEBUG] No metadata found for index', index);
                } else {
                console.log('[EMBEDDING DEBUG] Found metadata for index', index);
                }
                return history_item;
            })
            .filter(Boolean);

            // console.log('[EMBEDDING DEBUG] Final results:', topHistoryItems);

            if (topHistoryItems.length === 0) {
                console.log('[EMBEDDING DEBUG] No valid metadata found for any results');
            }

            return {
                results: topIndexMap,
                metadata: topHistoryItems
            };
        } catch (error) {
            console.error('[EMBEDDING DEBUG] Error searching index:', error);
            return {};
            // throw error;
        }
    }

}