// githubIssue.ts

import { getRepoContext, RepoContext, GithubOptions } from "./github_utils";
import { getGitHubHeaders } from "./githubAuth";

/**
 * Retrieves issue details or a list of recent issues for the repository.
 * 
 * @param number - A string representing an issue number (e.g., "123") or any non-number to list recent issues.
 * @param repoContext - A RepoContext object containing repository information.
 * @param options - (Optional) GithubOptions to override repo context (e.g., from a command-line flag).
 * @returns A formatted string containing the issue details or list of issues.
 */
export async function getIssueDetails(number: number, repoContext: RepoContext, options?: GithubOptions): Promise<object | string> {
  console.debug("getIssueDetails called with:", { number, repoContext, options });

  if (!repoContext) {
    console.debug("No repository context available.");
    return "Could not determine repository context. Please open a GitHub repository or specify one (e.g., using --from-github owner/repo).";
  }
  const { owner, repo } = repoContext;

  const issueNumber = number;
  let url: string;
  if (isNaN(issueNumber)) {
    url = `https://api.github.com/repos/${owner}/${repo}/issues?state=open&sort=created&direction=desc&per_page=10`;
  } else {
    url = `https://api.github.com/repos/${owner}/${repo}/issues/${issueNumber}`;
  }
  console.debug("Generated GitHub API URL:", url);

  try {
    //@ts-ignore
    const response = await fetch(url, {
      headers: getGitHubHeaders(),
    });
    console.debug("GitHub API response status:", response.status);
    
    if (!response.ok) {
      let errorMessage = `GitHub API Error: ${response.status} - ${response.statusText}`;
      if (response.status === 404) {
        errorMessage += `\n  (Issue ${issueNumber} not found or the repository is private without proper authentication)`;
      }
      console.error(errorMessage);
      return errorMessage;
    }

    const data: any = await response.json();
    const comments = await fetchComments(owner, repo, data.number);
    console.debug("Fetched2 issue data:", data, "\nFetched2 comments data:", comments);
    return {data, comments};
 
  } catch (error) {
    console.error("Error fetching issue details:", error);
    return `Error fetching issue details: ${error instanceof Error ? error.message : "Unknown error"}`;
  }
}

export async function fetchComments (owner: string, repo: string, issueNumber: number): Promise<any[]> {
  console.debug("Fetching comments for issue:", issueNumber);
  
  const url = `https://api.github.com/repos/${owner}/${repo}/issues/${issueNumber}/comments`;
  try {
    //@ts-ignore
    const response = await fetch(url, {
      headers: getGitHubHeaders(),
    });
    console.debug("GitHub API response status for comments:", response.status);
    
    if (!response.ok) {
      return [];
    }
    const data: any = await response.json();
    console.debug("Fetched comments data:", data);
    return data;
  } catch (error) {
    console.error("Error fetching comments:", error);
    return [];
  }
}