async function refreshSupabaseToken(
  panel: vscode.WebviewPanel
): Promise<string | null> {
  try {
    const localConfig = vscode.workspace.getConfiguration();
    const localStore = new StorageService(localConfig);
    const supabaseRefreshToken = await localStore.getValue(
      "gocodeo.supabaseRefreshToken"
    );
    console.log(
      "Trying supabase token refresh with refresh token",
      supabaseRefreshToken
    );
    const requestOptions = {
      method: "GET",
    };

    const response = await fetch(
      `${BASE_URL}/api/v1/supabase-token-refresh?refresh_token=${supabaseRefreshToken}`,
      requestOptions
    );
    console.log("supabase token refresh response", response);
    if (!response.ok) {
      console.error("Error refreshing token:", response?.statusText);
    }
    const data = await response.json();
    console.log("supabase refresh token result", data);
    if (data.access_token && data.refresh_token) {
      console.log(
        "Updating supabase access and refresh tokens",
        data.access_token,
        data.refresh_token
      );
      await localStore.setValue(
        "gocodeo.supabaseAccessToken",
        data.access_token
      );
      await localStore.setValue(
        "gocodeo.supabaseRefreshToken",
        data.refresh_token
      );
      panel.webview.postMessage({ command: "supabaseTokenRefreshed", data });
      return data.access_token;
    }
    return "";
  } catch (error) {
    console.error("Error refreshing token:", error);
    return null;
  }
}

