async function executeSupabaseSQL(
  sqlCommands,
  supabaseProjectID,
  supabaseProjectName,
  supabaseToken,
  panel
) {
  let sqlResult = "";
  try {
    console.log(
      "Executing Supabase SQL commands",
      sqlCommands,
      "\nsupabase project ID",
      supabaseProjectID,
      supabaseProjectName,
      supabaseToken
    );
    // const headers = new Headers();
    // headers.append("Content-Type", "application/json");
    // headers.append("Authorization", `Bearer ${supabaseToken}`);
    console.log(" new Headers() :", new Headers());

    const headers = {
      "Content-Type": "application/json",
      Authorization: `Bearer ${supabaseToken}`,
    };
    const raw = JSON.stringify({ query: sqlCommands });
    // const raw = JSON.stringify({ "query": "hello world" + sqlCommands });

    const requestOptions = {
      method: "POST",
      headers: headers,
      body: raw,
      redirect: "follow",
    };

    console.log("Supabase SQL Execution Request", requestOptions);
    const response = await fetch(
      `https://api.supabase.com/v1/projects/${supabaseProjectID}/database/query`,
      requestOptions
    );
    sqlResult = await response.json();
    console.log("Supabase SQL Execution Response", sqlResult);

    // if(sqlResult.message.replace(" ", "").includes('ERROR:42710')) {
    //   vscode.window.showInformationMessage("\"profiles\" already exists!");
    // } else {
    //   vscode.window.showErrorMessage("Failed to execute Supabase SQL. Please try again.");
    // }
    if (!response.ok) throw new Error("Failed to execute Supabase SQL");
    vscode.window.showInformationMessage("Supabase SQL successfully executed.");
    panel.webview.postMessage({
      command: "executeSupabaseSQLDone",
      parameter: {
        executedSuccessfully: true,
        message:
          sqlResult.message || "Successfully executed Supabase SQL commands",
      },
    });

    return sqlResult;
  } catch (error) {
    console.error("Error executing Supabase SQL:", error);
    console.error(
      "executeSupabaseSQLDone ext 22 :",
      sqlResult.message.includes("42710"),
      "\n ",
      sqlResult
    );
    if (
      sqlResult.message &&
      (sqlResult.message.includes("42710") ||
        sqlResult.message.includes("already exists"))
    ) {
      // Extract the actual error message after ERROR: 42710:
      const errorMessage = sqlResult.message.split("42710:")[1].trim();
      const formattedMessage = `Supabase SQL execution skipped: ${errorMessage}.`;
      panel.webview.postMessage({
        command: "executeSupabaseSQLDone",
        parameter: {
          executedSuccessfully: true,
          message:
            sqlResult.message || "Successfully executed Supabase SQL commands",
        },
      });

      vscode.window.showInformationMessage(formattedMessage);
    } else {
      panel.webview.postMessage({
        command: "executeSupabaseSQLDone",
        parameter: {
          executedSuccessfully: false,
          message: sqlResult.message,
          sql_table_content: sqlCommands,
        },
      });
      const errorRegex = /ERROR:\s+\d+:\s+(.*)/;
      const match = sqlResult.message.match(errorRegex);
      console.log("supabase sql error message regex match", match);
      if (match) {
        const errorMessage = match[1].trim();
        const formattedMessage = `Failed to Execute Supabase SQL: ${errorMessage}.`;
        vscode.window.showErrorMessage(formattedMessage);
      } else {
        vscode.window.showErrorMessage(
          "Failed to execute Supabase SQL. Please try running the commands on the SQL editor."
        );
      }
    }

    return [];
  }
}

