import { execSync } from 'child_process';

/**
 * Check if the GitHub CLI is available and logged in
 */
export function isGitHubCliAvailable(): boolean {
  try {
    console.log('Checking if GitHub CLI is installed...');
    execSync('command -v gh', { stdio: 'ignore' });
    
    console.log('GitHub CLI is installed. Checking authentication status...');
    execSync('gh auth status', { stdio: 'ignore' });
    
    console.log('GitHub CLI is authenticated.');
    return true;
  } catch (error) {
    console.log('GitHub CLI is not available or not authenticated:', error);
    return false;
  }
}

/**
 * Try to get GitHub credentials from git credential helper
 * Returns undefined if no credentials are found or if there's an error
 */
export function getGitCredentials(): { username: string; password: string } | undefined {
  try {
    console.log('Trying to get GitHub credentials using git credential helper...');
    const input = 'protocol=https\nhost=github.com\n\n';
    
    const output = execSync('git credential fill', {
      input,
      encoding: 'utf8',
      stdio: ['pipe', 'pipe', 'ignore'],
    });
    
    console.log('Git credential helper output:', output);
    
    const lines = output.split('\n');
    const credentials: { [key: string]: string } = {};
    
    for (const line of lines) {
      const [key, value] = line.split('=');
      if (key && value) {
        credentials[key.trim()] = value.trim();
      }
    }
    
    if (credentials.username && credentials.password) {
      console.log('Git credentials found.');
      return { username: credentials.username, password: credentials.password };
    }
    
    console.log('No valid Git credentials found.');
    return undefined;
  } catch (error) {
    console.log('Error retrieving Git credentials:', error);
    return undefined;
  }
}

let ghAuthLoginMessagePrinted = false;
/**
 * Try to get a GitHub token using various methods
 */
export function getGitHubToken(): string | undefined {
  if (process.env.GITHUB_TOKEN) {
    console.log('Using GitHub token from environment variable.');
    return process.env.GITHUB_TOKEN;
  }

  if (isGitHubCliAvailable()) {
    try {
      console.log('Attempting to retrieve GitHub token using gh CLI...');
      const token = execSync('gh auth token --scopes repo,read:user', {
        encoding: 'utf8',
        stdio: ['ignore', 'pipe', 'ignore'],
      }).trim();
      console.log('GitHub token retrieved using gh CLI.');
      return token;
    } catch (error) {
      if (!ghAuthLoginMessagePrinted) {
        console.error('Failed to generate GitHub token using gh CLI. Run `gh auth login` to login to GitHub CLI.', error);
        ghAuthLoginMessagePrinted = true;
      }
    }
  }

  console.log('Trying to get GitHub token from git credentials...');
  const credentials = getGitCredentials();
  if (credentials) {
    if (credentials.password.startsWith('ghp_') || credentials.password.startsWith('gho_')) {
      console.log('Using GitHub token from git credentials.');
      return credentials.password;
    }
  }

  console.log('No GitHub token found.');
  return undefined;
}

/**
 * Get GitHub authentication headers for API requests
 */
export function getGitHubHeaders(): Record<string, string> {
  console.log('Generating GitHub authentication headers...');
  const headers: Record<string, string> = {
    Accept: 'application/vnd.github.v3+json',
  };

  const token = getGitHubToken();
  console.log('GitHub token:', token);
  
  if (token) {
    console.log('Using token-based authentication for GitHub API.');
    headers['Authorization'] = `token ${token}`;
    return headers;
  }

  console.log('Trying basic authentication using git credentials...');
  const credentials = getGitCredentials();
  if (credentials) {
    const auth = Buffer.from(`${credentials.username}:${credentials.password}`).toString('base64');
    headers['Authorization'] = `Basic ${auth}`;
  }

  console.log('GitHub headers generated:', headers);
  return headers;
}

