    vscode.commands.registerCommand('gocodeo.indexBuildSession', async (sessionId: string) => {
      try {
        console.log("[indexBuildSession]: Indexing session ", sessionId);
        const userDataPath = process.platform === "win32"
          ? process.env.APPDATA || path.join(process.env.USERPROFILE || "", "AppData", "Roaming")
          : path.join(process.env.HOME || "", ".config");

        const buildSessionsPath = path.join(userDataPath, "gocodeo", "build_sessions");
        const buildIndicesPath = path.join(userDataPath, "gocodeo", "build_indices");
        const sessionFile = path.join(buildSessionsPath, `${sessionId}.json`);
        const indexPath = path.join(buildIndicesPath, `${sessionId}.index`);
        const metadataPath = path.join(buildIndicesPath, `${sessionId}_metadata.json`);

        // console.log(`[indexBuildSession] Processing session file: ${sessionFile}`);
        const sessionData = JSON.parse(fs.readFileSync(sessionFile, 'utf-8'));

        // Only process build history if there are multiple interactions
        const buildHistory = sessionData.buildHistory || [];
        if (buildHistory.length <= 1) {
          console.log(`Not enough interactions (${buildHistory.length}) in session ${sessionId} to create/update index`);
          return;
        }

        // Check if index exists
        const isExistingIndex = fs.existsSync(indexPath) && fs.existsSync(metadataPath);
        console.log(`${isExistingIndex ? 'Checking for new content in' : 'Creating new'} index for session ${sessionId}`);

        // Function to parse DD/MM/YYYY date format
        const parseDateString = (dateStr: string): number => {
          try {
            // Handle "DD/MM/YYYY, HH:mm:ss" format
            if (dateStr.includes('/')) {
              const [datePart, timePart] = dateStr.split(',').map(s => s.trim());
              const [day, month, year] = datePart.split('/').map(Number);
              const [hours, minutes, seconds] = timePart.split(':').map(Number);

              // Month is 0-based in Date constructor
              const date = new Date(year, month - 1, day, hours, minutes, seconds);
              const timestamp = date.getTime();

              if (!isNaN(timestamp)) {
                return timestamp;
              }
            }
            return Date.now();
          } catch (error) {
            console.error('Error parsing date string:', dateStr, error);
            return Date.now();
          }
        };

        // Function to safely convert timestamp to ISO string
        const toSafeISOString = (timestamp: number): string => {
          try {
            if (!timestamp || isNaN(timestamp)) return new Date().toISOString();
            const date = new Date(timestamp);
            if (isNaN(date.getTime())) return new Date().toISOString();
            return date.toISOString();
          } catch (error) {
            console.error('Error converting timestamp to ISO string:', error);
            return new Date().toISOString();
          }
        };

        // Function to parse and normalize timestamp
        const parseTimestamp = (timestamp: string): number => {
          try {
            if (!timestamp) return Date.now();

            // First try parsing as DD/MM/YYYY format
            if (timestamp.includes('/')) {
              const parsed = parseDateString(timestamp);
              // console.log('Parsed timestamp:', {
              //   original: timestamp,
              //   parsed: new Date(parsed).toISOString()
              // });
              return parsed;
            }

            // Try parsing as ISO string or other formats
            const parsed = Date.parse(timestamp);
            return isNaN(parsed) ? Date.now() : parsed;
          } catch (error) {
            console.error('Error parsing timestamp:', timestamp, error);
            return Date.now();
          }
        };

        // Sort build history by timestamp and filter out invalid timestamps
        buildHistory.sort((a, b) => {
          const timeA = parseTimestamp(a?.timestamp || '');
          const timeB = parseTimestamp(b?.timestamp || '');
          return timeA - timeB;
        });

        // Get the earliest and latest timestamps from build history
        const timestamps = buildHistory
          .filter(item => item && item.timestamp)
          .map(item => {
            const parsed = parseTimestamp(item.timestamp);
            // console.log('Parsed build history timestamp:', {
            //   original: item.timestamp,
            //   parsed: new Date(parsed).toISOString()
            // });
            return parsed;
          })
          .filter(time => !isNaN(time) && time > 0);

        if (timestamps.length === 0) {
          console.log('No valid timestamps found in build history');
          return;
        }

        const earliestTimestamp = Math.min(...timestamps);
        const latestTimestamp = Math.max(...timestamps);

        console.log('Build history timestamp range:', {
          earliest: toSafeISOString(earliestTimestamp),
          latest: toSafeISOString(latestTimestamp),
          earliestOriginal: buildHistory.find(item => parseTimestamp(item.timestamp) === earliestTimestamp)?.timestamp,
          latestOriginal: buildHistory.find(item => parseTimestamp(item.timestamp) === latestTimestamp)?.timestamp
        });

        if (isExistingIndex) {
          // Load existing metadata
          const existingMetadata = JSON.parse(fs.readFileSync(metadataPath, 'utf-8'));

          // Handle null lastBuildTimestamp by using the earliest timestamp we have
          const lastIndexedTimestamp = existingMetadata.lastBuildTimestamp || earliestTimestamp;

          console.log('Timestamp comparison:', {
            lastIndexed: toSafeISOString(lastIndexedTimestamp),
            latest: toSafeISOString(latestTimestamp),
            isNewer: latestTimestamp > lastIndexedTimestamp
          });

          // Find only the new interactions that happened after last indexing
          const newInteractions = buildHistory.filter(item => {
            if (!item || !item.timestamp) {
              console.log('Skipping item without timestamp');
              return false;
            }
            const itemTimestamp = parseTimestamp(item.timestamp);
            const isNewer = itemTimestamp > lastIndexedTimestamp;

            // if (isNewer) {
            //   console.log('Found newer interaction:', {
            //     timestamp: item.timestamp,
            //     parsed: toSafeISOString(itemTimestamp),
            //     lastIndexed: toSafeISOString(lastIndexedTimestamp)
            //   });
            // }

            return isNewer;
          });

          if (newInteractions.length === 0) {
            console.log('No new interactions since last indexing, skipping update');
            return;
          }

          console.log(`Found ${newInteractions.length} new interactions to index`);

          const textsToProcess = newInteractions
            .filter(item => {
              const hasQuestion = typeof item.question === 'string' && item.question.trim().length > 0;
              const hasAnswer = typeof item.answer === 'string' && item.answer.trim().length > 0;
              return hasQuestion || hasAnswer;
            })
            .map(item => {
              const question = item.question?.trim() || '';
              const answer = item.answer?.trim() || '';
              return `Question: ${question}\nAnswer: ${answer}`.trim();
            })
            .filter(text => text.length > 0);

          if (textsToProcess.length === 0) {
            console.log('No valid content in new interactions, skipping update');
            return;
          }

          // Create metadata for new interactions - one per history item
          const chunkMetadataList: ChunkMetadata[] = newInteractions
            .map((item, index) => {
              const hasQuestion = typeof item.question === 'string' && item.question.trim().length > 0;
              const hasAnswer = typeof item.answer === 'string' && item.answer.trim().length > 0;
              
              if (!hasQuestion && !hasAnswer) return null;

              // Find the original index of this item in the full buildHistory array
              const originalHistoryIndex = buildHistory.findIndex(historyItem => 
                historyItem.timestamp === item.timestamp && 
                historyItem.question === item.question &&
                historyItem.answer === item.answer
              );

              const question = item.question?.trim() || '';
              const answer = item.answer?.trim() || '';
              const text = `Question: ${question}\nAnswer: ${answer}`.trim();
              
              return {
                sessionId,
                chunkIndex: originalHistoryIndex,
                startIndex: 0,
                endIndex: text.length,
                timestamp: item.timestamp
              };
            })
            .filter(item => item !== null) as ChunkMetadata[];

          // console.log(`Metadata: ${JSON.stringify(chunkMetadataList)}`);

          const updatedMetadata = {
            chunks: [...existingMetadata.chunks, ...chunkMetadataList],
            lastBuildTimestamp: latestTimestamp,
            lastUpdateTime: Date.now()
          };
          await embeddingService.createAndStoreIndex(
            textsToProcess, sessionId, JSON.stringify(updatedMetadata, null, 2), 
            storedAuthToken, currentUserProfile?.id
          );
        } else {
          // For new indices, process all content
          const textsToProcess = buildHistory
            .filter(item => {
              if (!item) return false;
              const hasQuestion = typeof item.question === 'string' && item.question.trim().length > 0;
              const hasAnswer = typeof item.answer === 'string' && item.answer.trim().length > 0;
              return hasQuestion || hasAnswer;
            })
            .map(item => {
              const question = item.question?.trim() || '';
              const answer = item.answer?.trim() || '';
              return `Question: ${question}\nAnswer: ${answer}`.trim();
            })
            .filter(text => text.length > 0);

          // Create metadata for all history items - one per item
          const chunkMetadataList: ChunkMetadata[] = buildHistory
            .map((item, index) => {
              if (!item) return null;
              
              const hasQuestion = typeof item.question === 'string' && item.question.trim().length > 0;
              const hasAnswer = typeof item.answer === 'string' && item.answer.trim().length > 0;
              
              if (!hasQuestion && !hasAnswer) return null;

              const question = item.question?.trim() || '';
              const answer = item.answer?.trim() || '';
              const text = `Question: ${question}\nAnswer: ${answer}`.trim();
              
              return {
                sessionId,
                chunkIndex: index, // Use the index position in buildHistory
                startIndex: 0, // Not relevant for single-item embeddings
                endIndex: text.length,
                timestamp: item.timestamp
              };
            })
            .filter(item => item !== null) as ChunkMetadata[];

          // console.log(`Metadata: ${JSON.stringify(chunkMetadataList)}`);
          const initialMetadata = {
            chunks: chunkMetadataList,
            lastBuildTimestamp: latestTimestamp,
            lastUpdateTime: Date.now()
          };

          // Create new index
          await embeddingService.createAndStoreIndex(
            textsToProcess, sessionId, JSON.stringify(initialMetadata, null, 2), 
            storedAuthToken, currentUserProfile?.id
          );

          console.log('Initial metadata timestamp:', toSafeISOString(latestTimestamp));
        }

      } catch (error) {
        console.error(`Error indexing session ${sessionId}:`, error);
        throw error;
      }
    })
  
