// Helper function for sliding windows
function slidingWindows<T>(arr: T[], windowSize: number): T[][] {
    if (windowSize <= 0) return [];
    const result: T[][] = [];
    for (let i = 0; i <= arr.length - windowSize; i++) {
        result.push(arr.slice(i, i + windowSize));
    }
    return result;
}

