export async function updateAccountUsage(authToken: string, updatePayload: object) {
    try {
        console.log("Updating usage for", authToken, "updatePayload", updatePayload)
        const headers = {Authorization: `Bearer ${authToken}`, "Content-Type": "application/json"};
        const payload = JSON.stringify({
            "update_type": "account_usage",
            "update_payload": updatePayload
        });    
        const response = await axios.put(`${BASE_URL}/v1/users/account`, payload, {headers: headers});
        console.log("Update account usage response", response)
    }
    catch(error) {
        console.error("Error while updating usage", error);
    }


}


export async function updateUserProfile(token: string, profile: any) {
    try {
        console.log("Updating profile for", token, "profile", profile);
        profile.deviceId = profile.uniqueDeviceID;
        const headers = { "Content-Type": "application/json" , Authorization: token};
        const response = await axios.patch(`${BASE_URL}/v1/users/profile`, JSON.stringify(profile), { headers: headers });
        // If token is invalid. Delete token and Ask for login.
        // Clear token and show msg
        return response.data && response.data.user;
        //@ts-ignore
    } catch (error) {
        console.error("Error while updating profile", error);
    }
}

export function getNonce() {
    let text = "";
    const possible = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    for (let i = 0; i < 32; i++) {
        text += possible.charAt(Math.floor(Math.random() * possible.length));
    }
    return text;
}



export async function fetchPerplexityResponse(message: any) {
  const PPLX_API_KEY = message?.apiKey;
  if (!PPLX_API_KEY) {
    throw new Error("Perplexity API key is missing. Please set it in your environment variables.");
  }

  try {
    const response = await axios.post(
      'https://api.perplexity.ai/chat/completions',
      {
        model: 'sonar',
        messages: [
          {
            role: 'system',
            content:
              'Search the web to produce answers to questions. Your responses are for an automated system and should be precise, specific, and concise. Avoid unnecessary chat and formatting. Include code and examples.',
          },
          { role: 'user', content: message.query },
        ],
        stream: false,
        max_tokens: 4000,
      },
      {
        headers: {
          Authorization: `Bearer ${PPLX_API_KEY}`,
          'Content-Type': 'application/json',
          Accept: 'application/json',
        },
      }
    );

    return response.data;
  } catch (error: any) {
    console.error("Error fetching Perplexity API:", error.response?.data || error.message);
    throw new Error(
      `Failed to fetch data from Perplexity API. ${error.response?.data?.error || "Please check your internet connection or API key."}`
    );
  }
}

  
