 
import {  RepoContext, type GithubOptions} from './github_utils';
import { getGitHubHeaders  } from './githubAuth';

interface ReviewComment {
  path: string;
  position: number | null;
  line?: number;
  body: string;
  user: { login: string };
  created_at: string;
  html_url: string;
}

  async function fetchComments(owner: string, repo: string, prNumber: number): Promise<any> {
    const url = `https://api.github.com/repos/${owner}/${repo}/issues/${prNumber}/comments`;
    try {
      //@ts-ignore
      const response = await fetch(url, {
        headers: getGitHubHeaders(),
      });
  
      if (!response.ok) {
        return [];
      }
  
      return await response.json();
    } catch (error) {
      console.error('Error fetching comments:', error);
      return [];
    }
  }
  
  async function fetchReviewComments(owner: string, repo: string, prNumber: number): Promise<any> {
    const url = `https://api.github.com/repos/${owner}/${repo}/pulls/${prNumber}/comments`;
    try {
      //@ts-ignore
      const response = await fetch(url, {
        headers: getGitHubHeaders(),
      });
  
      if (!response.ok) {
        return [];
      }
  
      return await response.json();
    } catch (error) {
      console.error('Error fetching review comments:', error);
      return [];
    }
  }
  
 
  export async function getPRDetails(
    prNumber: number,
    repoContext: RepoContext,
    options?: GithubOptions
  ): Promise<object | string> {
    console.debug("getPRDetails called with:", { prNumber, repoContext, options });
  
    if (!repoContext) {
      console.debug("No repository context available.");
      return "Could not determine repository context. Please open a GitHub repository or specify one (e.g., using --from-github owner/repo).";
    }
    const { owner, repo } = repoContext;
  
    let url: string;
    if (isNaN(prNumber)) {
      url = `https://api.github.com/repos/${owner}/${repo}/pulls?state=open&sort=created&direction=desc&per_page=10`;
    } else {
      url = `https://api.github.com/repos/${owner}/${repo}/pulls/${prNumber}`;
    }
    console.debug("Generated GitHub API URL:", url);
  
    try {
      //@ts-ignore
      const response = await fetch(url, {
        headers: getGitHubHeaders(),
      });
      console.debug("GitHub API response status:", response.status);
  
      if (!response.ok) {
        let errorMessage = `GitHub API Error: ${response.status} - ${response.statusText}`;
        if (response.status === 404) {
          errorMessage += `\n  (PR ${prNumber} not found or the repository is private without proper authentication)`;
        }
        console.error(errorMessage);
        return errorMessage;
      }
  
      const data: any = await response.json();
  
      if (isNaN(prNumber)) {
        // Listing open PRs
        if (data.length === 0) {
          return "No open PRs found.";
        }
        // Return a summarized list of PRs
        return data.map((pr: any) => ({
          number: pr.number,
          title: pr.title,
          user: pr.user.login,
          url: pr.html_url,
        }));
      } else {
        // Single PR details
        const pr = data;
  
        // Fetch review comments (comments on code)
        const reviewComments = await fetchReviewComments(owner, repo, prNumber);
  
        // Fetch discussion comments
        const comments = await fetchComments(owner, repo, prNumber);
  
        console.debug("Fetched PR data:", pr, "\nReview comments:", reviewComments, "\nDiscussion comments:", comments);
  
        return {
          pr,
          reviewComments,
          comments,
        };
      }
    } catch (error) {
      console.error("Error fetching PR details:", error);
      return `Error fetching PR details: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
  }
  