const crypto = require("crypto");
const algorithm = "aes-256-cbc";
// const initVector = "\xba\xf9\xf2\x929\x0e>F\x80\xc4\x86\xb3\xff\xdbj\xa7";
const initVector = "GoCodeo63ae90857";
const getSecretKey = (secretKey:string)=>{
    return secretKey + 'GoCodeo1';
}
function createdecreyptKey(secretKey: string): Buffer { 
  const fullKey = secretKey + 'GoCodeo1';
  // console.log("ful key",fullKey )
  return Buffer.from(fullKey);
}

export const encrypt = (secretKey:string, data:string) => {
    secretKey = getSecretKey(secretKey);
    const cipher = crypto.createCipheriv(algorithm, secretKey, initVector);
    let encryptedData = cipher.update(data, "utf-8", "hex");
    encryptedData += cipher.final("hex");
    return encryptedData;
}
export const decrypt = (secretKey: string, encryptedData: string) => {
    try {
      // Use the fixed key that matches the Python implementation
      const key = createdecreyptKey(secretKey);
      const iv = Buffer.from(initVector);
      
      const decipher = crypto.createDecipheriv('aes-256-cbc', key, iv);
      let decryptedData = decipher.update(encryptedData, "hex", "utf-8");
      decryptedData += decipher.final("utf-8");
      return decryptedData;
    } catch (error) {
      console.error("Error decrypting data:", error);
      throw new Error("Failed to decrypt data: " + error.message);
    }
  };