const { execSync } = require('child_process');
import * as vscode from 'vscode';
import type { CommandOptions } from "./github_types";

export interface GithubOptions extends CommandOptions {
  repo?: string;
  fromGithub?: string;
}

export interface RepoContext {
  owner: string;
  repo: string;
}

function parseRepoString(repoStr: string): RepoContext | null {
  const parts = repoStr.split('/');
  if (parts.length === 2) {
    return { owner: parts[0], repo: parts[1] };
  } else {
    console.error("Invalid repository format. Use 'owner/repo'");
    return null;
  }
}

export async function getRepoContext(options?: GithubOptions): Promise<RepoContext | null> {
  try {
    // First try --from-github for consistency with other commands
    if (options?.fromGithub) {
      return parseRepoString(options.fromGithub);
    }

    // Then try --repo for backward compatibility
    if (options?.repo) {
      return parseRepoString(options.repo);
    }

    // Get workspace root path
    const workspaceRoot = vscode.workspace.workspaceFolders?.[0]?.uri.fsPath;
    if (!workspaceRoot) {
      throw new Error("No workspace folder found");
    }

    // Execute git command with proper options
    const remoteUrl = execSync('git config --get remote.origin.url', {
      cwd: workspaceRoot,  // Specify the working directory
      encoding: 'utf8',    // Get string output
      stdio: ['pipe', 'pipe', 'pipe']  // Handle I/O properly
    }).toString().trim();

    console.log("Remote URL:", remoteUrl);

    // Parse URL for both HTTPS and SSH formats
    let match;
    if (remoteUrl.startsWith('git@')) {
      // SSH URL format: git@github.com:owner/repo.git
      match = remoteUrl.match(/git@github\.com:(.*?)\/(.*?)(?:\.git)?$/);
    } else {
      // HTTPS URL format: https://github.com/owner/repo.git
      match = remoteUrl.match(/github\.com[:/](.*?)\/(.*?)(?:\.git)?$/);
    }

    if (!match) {
      throw new Error("Could not parse GitHub repository URL");
    }

    return {
      owner: match[1],
      repo: match[2]
    };

  } catch (error) {
    console.error("Error getting repo context:", error);
    return null;
  }
}
