import { getRepoContext, type RepoContext } from './github_utils';
import { execSync } from 'child_process';
import * as vscode from 'vscode';
import * as path from "path";
const fs = require("fs");

interface BranchResponse {
  name: string;
  commit: {
    sha: string;
    url: string;
  };
  protected: boolean;
}
interface CommitAndPRResponse {
    prNumber: number;
    prUrl: string;
    commitHash: string;
  }
interface CreatePRResponse {
  number: number;
  html_url: string;
  state: string;
  title: string;
  body: string;
}
function getLocalBranch(): string | null {
    try {
      // Get the workspace root path
      const workspaceRoot = vscode.workspace.workspaceFolders?.[0]?.uri.fsPath;
      if (!workspaceRoot) {
        console.log('No workspace folder found');
        return null;
      }
  
      console.log('Executing git command in:', workspaceRoot);
      
      // Execute git command with proper working directory
      const branch = execSync("git branch --show-current", {
        cwd: workspaceRoot,  // Specify the working directory
        encoding: 'utf8',
        stdio: ['pipe', 'pipe', 'pipe']
      }).toString().trim();
      
      console.log('Current local branch:', branch);
      return branch;
    } catch (error) {
      console.error('Error getting local branch:', error);
      return null;
    }
  }
  
  export async function getCurrentBranch(repoContext: RepoContext): Promise<string|undefined> {
    try {
      // First try to get local branch
      const localBranch = getLocalBranch();
      if (localBranch) {
        // Verify branch exists on remote
        const { owner, repo } = repoContext;
        const headers = getGitHubHeaders();
  
        try {
          const branchResponse = await fetch(
            `https://api.github.com/repos/${owner}/${repo}/branches/${localBranch}`,
            { headers }
          );
  
          if (branchResponse.ok) {
            console.log(`Verified branch ${localBranch} exists on remote`);
            return localBranch;
          }
        } catch (error) {
          console.warn(
            `Branch ${localBranch} not found on remote, but continuing with local branch`
          );
          return localBranch;
        }
      }
  
    } catch (error) {
      console.error("Error getting current branch:", error);
      return undefined;
    }
  }
  
 
  
  export async function commitAndCreatePR(
    repoContext: RepoContext,
    currentBranch: string,
    commitMessage: string = "Update changes",
    targetBranch: string = "main"
  ): Promise<CommitAndPRResponse> {
    try {
      const workspaceRoot = vscode.workspace.workspaceFolders?.[0]?.uri.fsPath;
      if (!workspaceRoot) {
        throw new Error('No workspace folder found');
      }
  
     console.log("targetBranch",targetBranch)
      const { owner, repo } = repoContext;
      const headers = await getGitHubHeaders(); 
  
      // Check repository access
      const repoCheckResponse = await fetch(
        `https://api.github.com/repos/${owner}/${repo}`,
        { headers }
      );
  
      if (!repoCheckResponse.ok) {
        throw new Error(`Repository access failed: ${repoCheckResponse.statusText}`);
      }
  


      console.log('Adding all changes...');
      const detectedTechStack = detectTechStack(workspaceRoot);
      const gitignorePath = path.join(workspaceRoot, ".gitignore");
      if (!fs.existsSync(gitignorePath)) {
        console.log(".gitignore not found. Creating one...");
        let gitignoreContent = "";
        switch (detectedTechStack) {
          case 'node':
            gitignoreContent = `node_modules/
  dist/
  .env
  `;
            break;
          case 'python':
            gitignoreContent = `__pycache__/
  *.pyc
  env/
  `;
            break;
          case 'java':
            gitignoreContent = `target/
  *.class
  `;
            break;
          default:
            gitignoreContent = `node_modules/
  dist/
  .env
  `;
            break;
        }
      fs.writeFileSync(gitignorePath, gitignoreContent);
      console.log(".gitignore created with content:", gitignoreContent);
    } else {
      console.log(".gitignore already exists.");
    }

      execSync('git add .', {
        cwd: workspaceRoot,
        stdio: 'pipe'
      });
  
      console.log('Creating commit...');
      execSync(`git commit -m "${commitMessage}"`, {
        cwd: workspaceRoot,
        stdio: 'pipe'
      });
  
      const commitHash = execSync('git rev-parse HEAD', {
        cwd: workspaceRoot,
        encoding: 'utf8',
        stdio: 'pipe'
      }).trim();
  

      const token = headers.Authorization?.replace('token ', '') || 
                   headers.Authorization?.replace('Bearer ', '');
      
      if (!token) {
        throw new Error('No GitHub token found');
      }
  

      const remoteUrl = `https://${token}@github.com/${owner}/${repo}.git`;
      console.log("remote url got",remoteUrl)
      try {
        execSync(`git remote set-url origin "${remoteUrl}"`, {
          cwd: workspaceRoot,
          stdio: 'pipe'
        });
  
        console.log('Pushing to remote...');
        execSync(`git push origin ${currentBranch}`, {
          cwd: workspaceRoot,
          stdio: 'pipe'
        });
      } finally {
     
        execSync(`git remote set-url origin "https://github.com/${owner}/${repo}.git"`, {
          cwd: workspaceRoot,
          stdio: 'pipe'
        });
      }
  
      const branchCheckResponse = await fetch(
        `https://api.github.com/repos/${owner}/${repo}/branches/${currentBranch}`,
        { headers }
      );
  
      if (!branchCheckResponse.ok) {
        throw new Error(`Branch verification failed after push: ${branchCheckResponse.statusText}`);
      }
  
      // 5. Check if PR already exists
    //   const existingPRsResponse = await fetch(
    //     `https://api.github.com/repos/${owner}/${repo}/pulls?head=${owner}:${currentBranch}&base=${targetBranch}&state=open`,
    //     { headers }
    //   );
  
    //   if (existingPRsResponse.ok) {
    //     const existingPRs = await existingPRsResponse.json();
    //     if (existingPRs.length > 0) {
    //       console.log('PR already exists, returning existing PR details');
    //       return {
    //         prNumber: existingPRs[0].number,
    //         prUrl: existingPRs[0].html_url,
    //         commitHash
    //       };
    //     }
    //   }
  

      console.log('Creating Pull Request...');
      const prResponse = await fetch(
        `https://api.github.com/repos/${owner}/${repo}/pulls`,
        {
          method: 'POST',
          headers: {
            ...headers,
            'Accept': 'application/vnd.github.v3+json',
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            title: `Updates from ${currentBranch}`,
            head: currentBranch,  
            base: targetBranch,
            body: `Automated PR from ${currentBranch}\nCommit: ${commitHash}`,
            maintainer_can_modify: true
          })
        }
      );
      
      if (!prResponse.ok) {
        const errorData = await prResponse.json();
        console.error('PR creation response:', errorData);
        
        // Add more detailed error logging
        if (errorData.errors) {
          console.log('Current branch:', currentBranch);
          console.log('Target branch:', targetBranch);
          console.log('Owner:', owner);
          console.log('Repo:', repo);
        }
        
        // If it's a head reference error, try with full reference
        if (errorData.errors?.some(e => e.field === 'head' && e.code === 'invalid')) {
          console.log('Retrying with full head reference...');
          const fullHeadResponse = await fetch(
            `https://api.github.com/repos/${owner}/${repo}/pulls`,
            {
              method: 'POST',
              headers: {
                ...headers,
                'Accept': 'application/vnd.github.v3+json',
                'Content-Type': 'application/json',
              },
              body: JSON.stringify({
                title: `Updates from ${currentBranch}`,
                head: `${owner}:${currentBranch}`,  // Try with full reference
                base: targetBranch,
                body: `Automated PR from ${currentBranch}\nCommit: ${commitHash}`,
                maintainer_can_modify: true
              })
            }
          );
      
          if (!fullHeadResponse.ok) {
            const fullHeadError = await fullHeadResponse.json();
            throw new Error(`PR creation failed: ${fullHeadError.message}\nErrors: ${JSON.stringify(fullHeadError.errors)}`);
          }
      
          const prData = await fullHeadResponse.json();
          return {
            prNumber: prData.number,
            prUrl: prData.html_url,
            commitHash
          };
        }
      
        throw new Error(`PR creation failed: ${errorData.message}\nErrors: ${JSON.stringify(errorData.errors)}`);
      }
      
      const prData = await prResponse.json();
      return {
        prNumber: prData.number,
        prUrl: prData.html_url,
        commitHash
      };
    } catch (error) {
      console.error('Error in commitAndCreatePR:', error);
      throw error;
    }
  }
