export async function createPullRequest(
  title: string,
  sourceBranch: string,
  targetBranch: string = 'main',
  description: string = ''
): Promise<CreatePRResponse> {
  try {
    const repoContext = await getRepoContext();
    if (!repoContext) {
      throw new Error('Could not determine repository context');
    }

    const { owner, repo } = repoContext;
    const response = await fetch(
      `https://api.github.com/repos/${owner}/${repo}/pulls`,
      {
        method: 'POST',
        headers: getGitHubHeaders(),
        body: JSON.stringify({
          title,
          head: sourceBranch,
          base: targetBranch,
          body: description
        })
      }
    );

    if (!response.ok) {
      const errorData = await response.json();
      throw new Error(`Failed to create PR: ${errorData.message}`);
    }

    return await response.json();
  } catch (error) {
    console.error('Error creating pull request:', error);
    throw new Error(`Failed to create pull request: ${error instanceof Error ? error.message : 'Unknown error'}`);
  }
}

// Example usage function
export async function createFeaturePR(featureBranch: string = 'feature/cli'): Promise<void> {
  try {
    // Get repository context
    const repoContext = await getRepoContext();
    if (!repoContext) {
      throw new Error('Could not determine repository context');
    }

    // Create PR
    const prResponse = await createPullRequest(
      `Feature: ${featureBranch}`, // Title
      featureBranch,               // Source branch
      'main',                      // Target branch
      'Automated PR creation for feature branch' // Description
    );

    console.log('Pull Request created successfully:', {
      number: prResponse.number,
      url: prResponse.html_url
    });
  } catch (error) {
    console.error('Error in createFeaturePR:', error);
    throw error;
  }
}